MATCH (start:`VehiclePosture(汽车姿态)`)
WITH start, (
  EXISTS {
    MATCH (start:`VehiclePosture(汽车姿态)`)<-[:`StyleAssociatedWith`]-(s1:`汽车风格`)
  }
  OR EXISTS {
    MATCH (start:`VehiclePosture(汽车姿态)`)<-[:`TypeAssociatedWith`]-(s1:`汽车车型`)
  }
) AS connected
RETURN count(start) AS total_start_nodes,
       sum(CASE WHEN connected THEN 1 ELSE 0 END) AS connected_start_nodes

